test:
bad_calls = [
    lambda: simulate_with_immunity([]),
    lambda: simulate_with_immunity([[1], [2, 0]]),
    lambda: simulate_with_immunity([[3]]),
    lambda: simulate_with_immunity([[1]], infection_threshold=0),
]
for call in bad_calls:
    try:
        call()
        assert False, 'expected ValueError'
    except ValueError:
        pass
